/// <summary>
/// VM - CB264 - Pickupslot
/// Table to store the Split category code with area.
/// </summary>
public class METOrderSplitCategoryArea extends common
{
}

Method.Source:
    /// <summary>
    /// Find the Category Area in the table
    /// </summary>
    /// <param name = "_categoryCode">code value to find</param>
    /// <param name = "update">Pass true if update is required</param>
    /// <returns>METOrderSplitCategoryArea</returns>
    static METOrderSplitCategoryArea find(METCategoryCode _categoryCode, boolean update = false)
    {
        METOrderSplitCategoryArea metOrderSplitCategoryArea;
        
        if (_categoryCode)
        {
            select firstonly metOrderSplitCategoryArea
                    index hint SplitCategoryIdx
                where metOrderSplitCategoryArea.CategoryArea == _categoryCode;

            metOrderSplitCategoryArea.selectForUpdate(update);
        }
        return metOrderSplitCategoryArea;
    }

/// <summary>
/// Check if record with category area exist
/// </summary>
/// <param name = "_categoryCode">Category Code to find the value</param>
/// <returns>returns boolean value</returns>
public static boolean exist(METCategoryCode _categoryCode)
{
    return _categoryCode && (select firstonly RecId from METOrderSplitCategoryArea
                        index hint SplitCategoryIdx
                            where METOrderSplitCategoryArea.CategoryArea == _categoryCode).RecId != 0;
}

    /// <summary>
    /// Assign value to New category
    /// </summary>
    /// <param name = "_fieldId">_fieldId</param>
    public void modifiedField(fieldId _fieldId)
    {
        switch(_fieldId)
        {
            case fieldnum(METOrderSplitCategoryArea, OSCC):
            case fieldnum(METOrderSplitCategoryArea, Area):
                this.CategoryArea = this.OSCC;
                if(this.Area)
                {
                    this.CategoryArea = this.OSCC + METConstants::hyphen + this.Area;
                }
                break;

            default:
                super(_fieldId);
        }
    }
